/**
 * SHARED CONTRACTS. Every system is built against these interfaces and nothing else.
 * Do not edit this file from inside a system; if something is missing, work around it
 * locally and report it so the lead can extend the contract.
 *
 * Co-op rules (see PLAN.md §9): sim state is plain serializable data with string ids,
 * presentation only reads it, players are a registry, loot is owned per player.
 */
import type * as THREE from 'three';
import type { EventBus } from './events';
import type { Input } from './input';
import type { GearDef, Loadout } from '@/gear/types';

// ---------------------------------------------------------------------------
// Basic vocab
// ---------------------------------------------------------------------------
export type Rarity = 'common' | 'uncommon' | 'rare' | 'epic' | 'legendary';
export const RARITY_ORDER: readonly Rarity[] = ['common', 'uncommon', 'rare', 'epic', 'legendary'];
export const RARITY_COLORS: Record<Rarity, number> = {
  common: 0xdddddd,
  uncommon: 0x3ddc5b,
  rare: 0x3b8bff,
  epic: 0xb04dff,
  legendary: 0xff9a1f,
};

export type Element = 'none' | 'fire' | 'shock' | 'ice';
export const ELEMENT_COLORS: Record<Element, number> = {
  none: 0xffe9b0,
  fire: 0xff5a1f,
  shock: 0x4fd9ff,
  ice: 0x9fe8ff,
};

export type WeaponArchetype = 'pistol' | 'smg' | 'shotgun' | 'rifle' | 'sniper';
export type MobKind = 'grunt' | 'spitter' | 'bomber';
export type BossKind = 'brute' | 'summoner' | 'artillery';

/** Plain {x,y,z} used in serializable state. Convert with THREE.Vector3.set(v.x,v.y,v.z). */
export interface Vec3 { x: number; y: number; z: number }

// ---------------------------------------------------------------------------
// Weapons (generated by loot, consumed by player)
// ---------------------------------------------------------------------------
export interface WeaponPerk {
  id: string; // e.g. 'ricochet', 'crit_refund', 'ramp_up', 'splash', 'lifesteal'
  name: string;
  description: string;
}

export interface WeaponDef {
  id: string;
  name: string; // generated, e.g. "Molten Jakko Ripper"
  archetype: WeaponArchetype;
  rarity: Rarity;
  element: Element;
  level: number; // tier it dropped at
  damage: number; // per pellet
  fireRate: number; // shots per second
  auto: boolean; // hold to fire
  magSize: number;
  reloadTime: number; // seconds
  pellets: number; // 1 for most, 6-10 for shotguns
  spread: number; // radians, cone half-angle (base/first-shot; derived from accuracy)
  /** 0..100 shown on the card; spread = config spreadFromAccuracy(accuracy). */
  accuracy: number;
  /** Aim-down-sights FOV divisor (1 = no zoom; snipers ~3). */
  zoom: number;
  /** Spread multiplier while aiming down sights. */
  adsSpread: number;
  range: number; // metres
  critMultiplier: number;
  elementChance: number; // 0..1 chance per hit to apply the status (0 when element === 'none')
  perks: WeaponPerk[];
  color: number; // body colour of the gun (rarity/element tinted)
}

// ---------------------------------------------------------------------------
// Players
// ---------------------------------------------------------------------------
/** Multipliers from the skill tree. Player/weapon code reads ctx.progression.stats every shot. */
export interface PlayerStats {
  damageMult: number;
  fireRateMult: number;
  reloadMult: number; // <1 is faster
  critMult: number;
  healthMult: number;
  shieldMult: number;
  moveSpeedMult: number;
}

/** What dealt a hit (hype styles, set hooks, attribution). */
export type DamageCause = 'bullet' | 'melee' | 'grenade' | 'status' | 'explosion' | 'other';

export interface DamageOpts {
  point?: THREE.Vector3; // world hit point, for numbers/effects
  element?: Element;
  crit?: boolean;
  sourceId?: string; // playerId (or enemy id) that dealt the damage
  applyStatus?: boolean; // whether to roll the elemental status
  /** Area damage (damageRadius) skips the enemy with this id (e.g. the target a splash came from). */
  excludeId?: string;
  /** What dealt the hit; carried into damage:dealt / enemy:killed. Default 'other'. */
  cause?: DamageCause;
}

/** One player, local or remote. Only the local one has a controller behind it. */
export interface PlayerState {
  readonly id: string;
  readonly name: string;
  readonly isLocal: boolean;
  /** Feet position, world space. Mutated by the controller; read by everyone else. */
  readonly position: THREE.Vector3;
  readonly velocity: THREE.Vector3;
  /** Yaw/pitch of the view, radians. */
  readonly yaw: number;
  readonly pitch: number;
  health: number;
  maxHealth: number;
  shield: number;
  maxShield: number;
  readonly alive: boolean;
  readonly weapons: (WeaponDef | null)[];
  readonly activeSlot: number;
  readonly activeWeapon: WeaponDef | null;
  /** Equipped gear (local: the inventory's loadout; remote: from snapshots, for avatars). */
  readonly loadout: Readonly<Loadout>;
  /** True while standing on ground (hype "airborne" kills, set hooks). */
  readonly onGround: boolean;
  /** Aiming down sights (local player; remote players leave it undefined). */
  readonly aiming?: boolean;
  /** Current ADS zoom of the active weapon while aiming (1 when not aiming). */
  readonly zoom?: number;
  /** Current effective spread (radians) incl. movement, ADS and bloom, for the crosshair. */
  readonly spread?: number;
  grenades: number;
  ammo: number; // rounds in the current magazine
  reserve: number; // reserve rounds for the active weapon
  takeDamage(amount: number, opts?: DamageOpts): void;
  heal(amount: number): void;
  /** Add reserve ammo as a fraction of the weapon's magSize * 4 (ammo pickups). */
  addAmmo(fraction: number): void;
  addGrenades(n: number): void;
  /** Put the weapon in the active slot (or an empty one). Returns the replaced weapon, if any. */
  equip(weapon: WeaponDef): WeaponDef | null;
  /**
   * Full restore for a new run (health, shield, grenades, ammo, position). Weapons and gear are
   * KEPT (loot persists across runs like the skill tree); the caller only adds a starter weapon
   * when both slots are empty.
   */
  reset(): void;
  /** Bring a downed player back in place with a fraction of max health (co-op revives). No-op if alive. */
  revive(healthFraction: number): void;
}

export interface PlayerRegistry {
  readonly local: PlayerState;
  list(): PlayerState[];
  get(id: string): PlayerState | undefined;
  /** Closest living player to a point, or undefined if all are dead. */
  nearest(point: THREE.Vector3): PlayerState | undefined;
  add(p: PlayerState): void;
  remove(id: string): void;
}

// ---------------------------------------------------------------------------
// Enemies
// ---------------------------------------------------------------------------
export interface StatusEffect {
  element: Element;
  remaining: number; // seconds
  strength: number; // burn dps, slow factor, shock mult
  sourceId?: string;
}

/** Serializable sim state of one enemy. The view reads it; the sim mutates it. */
export interface EnemyState {
  id: string;
  kind: MobKind | BossKind;
  isBoss: boolean;
  tier: number;
  position: Vec3;
  yaw: number;
  health: number;
  maxHealth: number;
  alive: boolean;
  phase: number; // bosses: 0,1,2...
  anim: string; // 'idle' | 'walk' | 'attack' | 'hit' | 'die' | custom
  statuses: StatusEffect[];
}

export interface Enemy {
  readonly id: string;
  readonly state: EnemyState;
  /** Root object for raycasts (hitscan tests against its descendants). */
  readonly object: THREE.Object3D;
  readonly isBoss: boolean;
  readonly position: THREE.Vector3; // live world position (same as state.position)
  readonly alive: boolean;
  /** Approx. collision radius and height, for melee/grenade/sphere checks. */
  readonly radius: number;
  readonly height: number;
  /** True when a world point counts as a critical hit (head/weak point). */
  isCritPoint(point: THREE.Vector3): boolean;
  /**
   * Deal damage. Returns the damage actually applied (0 when dead/immune). Co-op mirrors
   * return the predicted amount (the host confirms it).
   */
  damage(amount: number, opts?: DamageOpts): number;
  applyStatus(status: StatusEffect): void;
}

export interface EnemyRegistry {
  list(): Enemy[];
  get(id: string): Enemy | undefined;
  spawnMob(kind: MobKind | 'random', position: THREE.Vector3, tier: number): Enemy;
  spawnBoss(kind: BossKind | 'auto', position: THREE.Vector3, tier: number): Enemy;
  /** Area damage with linear falloff. Returns the number of enemies hit. */
  damageRadius(center: THREE.Vector3, radius: number, amount: number, opts?: DamageOpts): number;
  aliveCount(): number;
  bossAlive(): boolean;
  /** Remove everything immediately (new run / cleanup). */
  clear(): void;
  update(dt: number): void;
}

// ---------------------------------------------------------------------------
// World
// ---------------------------------------------------------------------------
export interface CapsuleResult {
  position: THREE.Vector3;
  onGround: boolean;
}

export interface RayHit {
  point: THREE.Vector3;
  normal: THREE.Vector3;
  distance: number;
}

export interface WorldQuery {
  readonly playerStart: THREE.Vector3;
  readonly mobSpawnPoints: THREE.Vector3[];
  readonly bossSpawn: THREE.Vector3;
  /** Ground height at x,z (0 on flat snow, higher on ramps/platforms). */
  groundHeight(x: number, z: number): number;
  /**
   * Resolve a vertical capsule (feet at `position`) against static geometry and the arena
   * bounds. Returns the corrected feet position and whether it rests on ground.
   */
  resolveCapsule(position: THREE.Vector3, radius: number, height: number): CapsuleResult;
  /** Ray against static geometry only (walls, props, ground). */
  raycast(origin: THREE.Vector3, direction: THREE.Vector3, maxDistance: number): RayHit | null;
  /** Random point on the ground, inside the arena, away from obstacles. */
  randomNavigablePoint(minDistFrom?: THREE.Vector3, minDist?: number): THREE.Vector3;
  update(dt: number): void;
}

// ---------------------------------------------------------------------------
// Rendering helpers (provided by src/rendering)
// ---------------------------------------------------------------------------
export interface ToonOptions {
  color: THREE.ColorRepresentation;
  emissive?: THREE.ColorRepresentation;
  emissiveIntensity?: number;
  /** Legacy (hatching was removed with the Brutalist Arena look); accepted and ignored. */
  hatch?: boolean;
  /** Surface kind (docs/ART_DIRECTION.md §2.2), default 'concrete'. */
  surface?: 'concrete' | 'steel' | 'paint' | 'character' | 'flat';
  /** Overrides for the surface defaults: mottle 0..0.15, sheen 0..0.3, rim 0..0.5. */
  mottle?: number;
  sheen?: number;
  rim?: number;
}

export interface MaterialFactory {
  /** Cel-shaded material. Has `.color` and `.emissive` (MeshToonMaterial-compatible) so systems can tint/flash it. */
  toon(opts: ToonOptions): THREE.MeshToonMaterial;
  /** Unlit glowing material that blooms (tracers, beams, lanterns, aurora bits). */
  glow(color: THREE.ColorRepresentation, intensity?: number): THREE.MeshBasicMaterial;
}

export interface Fx {
  tracer(from: THREE.Vector3, to: THREE.Vector3, color: number, width?: number): void;
  impact(point: THREE.Vector3, normal: THREE.Vector3, color: number): void;
  explosion(center: THREE.Vector3, radius: number, color: number): void;
  /** Burst of particles (blood/ice chips/sparks) at a point. */
  burst(point: THREE.Vector3, color: number, count?: number): void;
  /** Camera shake, 0..1. */
  shake(amount: number): void;
  /** Full-screen tint flash (damage red, shield blue, level-up gold). */
  flash(color: number, strength?: number): void;
  update(dt: number): void;
}

// ---------------------------------------------------------------------------
// Loot
// ---------------------------------------------------------------------------
export type LootKind = 'weapon' | 'ammo' | 'health' | 'grenade' | 'gear';

export interface LootItemState {
  id: string;
  kind: LootKind;
  rarity: Rarity;
  position: Vec3;
  ownerId: string; // player who can pick it up (per-player loot instancing)
  weapon?: WeaponDef;
  gear?: GearDef;
  age: number;
}

/** An existing item to put on the ground (backpack drops, swapped weapons, co-op). */
export type LootDropSpec = Omit<LootItemState, 'id' | 'ownerId' | 'age'> & { id?: string; ownerId?: string; age?: number };

export interface DropOpts {
  tier: number;
  ownerId?: string; // default: every player gets their own instance
  /** 0..1, pushes the rarity roll up (bosses). */
  rarityBoost?: number;
  count?: number;
  /** Force these kinds (e.g. a boss always drops at least one weapon). */
  guaranteed?: LootKind[];
}

export interface LootSystem {
  items(): LootItemState[];
  dropLoot(position: THREE.Vector3, opts: DropOpts): LootItemState[];
  generateWeapon(tier: number, rarity?: Rarity): WeaponDef;
  starterWeapon(): WeaponDef;
  /** Put one specific item on the ground (default owner: the local player). Emits loot:dropped. */
  dropItem(spec: LootDropSpec): LootItemState;
  /** Remove one item (picked up elsewhere / co-op). Returns true if it existed. No event. */
  remove(id: string): boolean;
  clear(): void;
  update(dt: number): void;
}

// ---------------------------------------------------------------------------
// Progression
// ---------------------------------------------------------------------------
export interface SkillNode {
  id: string;
  name: string;
  description: string; // may contain {value} for the per-rank amount
  maxRank: number;
  /** Apply rank r to the stats object (mutates). */
  apply(stats: PlayerStats, rank: number): void;
  branch: string; // 'gunplay' | 'survival' | 'mobility' ... for layout
  requires?: string; // another node id that needs rank>=1 first
}

export interface Progression {
  readonly level: number;
  readonly xp: number;
  readonly xpToNext: number;
  readonly skillPoints: number;
  readonly stats: PlayerStats; // recomputed whenever a skill changes
  readonly skills: SkillNode[];
  rank(skillId: string): number;
  canUpgrade(skillId: string): boolean;
  upgrade(skillId: string): boolean;
  addXp(amount: number): void;
  save(): void;
  load(): void;
  resetTree(): void; // refund all points
}

// ---------------------------------------------------------------------------
// Rounds
// ---------------------------------------------------------------------------
export type RoundPhase = 'idle' | 'intermission' | 'wave' | 'boss' | 'cleared' | 'gameover';

export interface RoundState {
  round: number;
  phase: RoundPhase;
  phaseTime: number; // seconds in current phase
  killsRequired: number;
  kills: number;
  subWave: number;
  totalKills: number;
  bossKind?: BossKind;
}

export interface RoundManager {
  readonly state: RoundState;
  /** Begin a run at round 1 (resets player, enemies, loot). */
  start(): void;
  update(dt: number): void;
}

// ---------------------------------------------------------------------------
// Audio
// ---------------------------------------------------------------------------
export type SfxName =
  | 'shot_pistol' | 'shot_smg' | 'shot_shotgun' | 'shot_rifle' | 'shot_sniper'
  | 'reload' | 'empty' | 'equip' | 'melee' | 'grenade_throw' | 'explosion'
  | 'hit' | 'crit' | 'enemy_hurt' | 'enemy_die' | 'boss_roar' | 'boss_die' | 'spitter_shot' | 'bomber_fuse'
  | 'player_hurt' | 'shield_break' | 'shield_recharge' | 'player_die'
  | 'pickup' | 'pickup_weapon' | 'levelup' | 'skill_up'
  | 'round_start' | 'round_clear' | 'ui_click' | 'ui_open';

export type MusicState = 'menu' | 'intermission' | 'wave' | 'boss' | 'cleared' | 'dead';

export interface AudioSystem {
  play(name: SfxName, opts?: { position?: THREE.Vector3; volume?: number; pitch?: number }): void;
  setMusic(state: MusicState): void;
  /** Must be called from a user gesture to unlock the AudioContext. */
  resume(): void;
  /** Mute-all. Persisted; muted by default. */
  readonly muted: boolean;
  setMuted(muted: boolean): void;
  update(dt: number): void;
}

// ---------------------------------------------------------------------------
// UI
// ---------------------------------------------------------------------------
export type Screen = 'none' | 'start' | 'pause' | 'skills' | 'inventory' | 'gameover';

export interface Hud {
  readonly screen: Screen;
  showScreen(screen: Screen): void;
  update(dt: number): void;
}

// ---------------------------------------------------------------------------
// Game context (passed to every factory). Fields marked "boot" are assigned in
// main.ts in boot order; read them in update(), never in your factory body
// unless they come earlier in the boot order.
// Boot order: materials, fx, audio → world → players → enemies → loot → progression → standing →
// gear → hud → rounds → net
// ---------------------------------------------------------------------------
export interface GameContext {
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  renderer: THREE.WebGLRenderer;
  canvas: HTMLCanvasElement;
  uiRoot: HTMLElement;
  input: Input;
  events: EventBus;
  time: { delta: number; elapsed: number };
  /** Seeded RNG in [0,1). Sim code uses this, never Math.random(). */
  rng: () => number;
  /** True on the simulating peer (always true in single-player). */
  isHost: boolean;
  nextId(prefix: string): string;

  materials: MaterialFactory; // boot
  fx: Fx; // boot
  audio: AudioSystem; // boot
  world: WorldQuery; // boot
  players: PlayerRegistry; // boot
  /** Shortcut for players.local. */
  player: PlayerState; // boot
  enemies: EnemyRegistry; // boot
  loot: LootSystem; // boot
  progression: Progression; // boot
  hud: Hud; // boot
  rounds: RoundManager; // boot
  /**
   * Optional meta systems. main.ts wires all three (standing + gear right after progression,
   * net after rounds), but tests and tools may boot without them: read them with `?.`.
   */
  /** Standing, crowd favour (hype) and the sponsor contract. Read run modifiers from here. */
  standing?: import('@/standing').StandingSystem;
  /** Gear inventory/loadout; `mergedStats` folds it into the player stats (player/shared getStats). */
  gear?: import('@/gear').GearSystem;
  /** Co-op session (role 'offline' in single-player). */
  net?: import('@/net/session').NetSession;
}
